import java.util.HashMap; 
import java.util.Map; 

public class TwoSum { 
    public int[] twoSum(int[] nums, int target) { 
        Map<Integer, Integer> seen = new HashMap<>(); 
        for (int i = 0; i < nums.length; i++) { 
            int complement = target - nums[i]; 
            if (seen.containsKey(complement)) { 
                return new int[] { seen.get(complement), i }; 
            } 
            seen.put(nums[i], i); 
        } 
        throw new IllegalArgumentException("No solution found"); 
    } 

    public static void main(String[] args) { 
        TwoSum solver = new TwoSum(); 
        int[] result = solver.twoSum(new int[] {2, 7, 11, 15}, 9); 
        System.out.println(result[0] + ", " + result[1]); 
    } 
}

class Solution {
    public TreeNode insertIntoBST(TreeNode root, int val) {
        if(root==null){
            return new TreeNode(val);
        }
        if(root.val<val){
            root.right=insertIntoBST(root.right,val);
        }
        else{
            root.left=insertIntoBST(root.left,val);
        }
        return root;
    }
}

class Solution {
    public boolean areAnagrams(Node root1, Node root2) {
        Queue<Node> q1=new LinkedList<>();
        Queue<Node> q2=new LinkedList<>();
        q1.offer(root1);
        q2.offer(root2);
        while(!q1.isEmpty() || !q2.isEmpty()){
           int s1=q1.size();
           int s2=q2.size();
           if(s1!=s2){
               return false;
           }
           Map<Integer,Integer> map=new HashMap<>();
           for(int i=0;i<s1;i++){
               Node curr=q1.poll();
               map.put(curr.data,map.getOrDefault(curr.data,0)+1);
               if(curr.left!=null){
                   q1.offer(curr.left);
               }
               if(curr.right!=null){
                   q1.offer(curr.right);
               }
           }
           for(int i=0;i<s2;i++){
               Node curr=q2.poll();
               if(!map.containsKey(curr.data)){
                   return false;
               }
               map.put(curr.data,map.get(curr.data)-1);
               if(map.get(curr.data)==0){
                   map.remove(curr.data);
               }
               if(curr.left!=null){
                   q2.offer(curr.left);
               }
               if(curr.right!=null){
                   q2.offer(curr.right);
               }

           }
           if(!map.isEmpty()) {
               return false;
           }
        }

        return q1.isEmpty() && q2.isEmpty();

    }
}

class Solution {
    public List<Integer> reverseLevelOrder(Node root) {
        LinkedList<Node> ll=new LinkedList<>();
        LinkedList<Integer> result=new LinkedList<>();
        if(root==null){
            return result;
        }
        ll.addFirst(root);
        while(!ll.isEmpty()){
            int size=ll.size();
            for(int i=0;i<size;i++){
                Node node=ll.pollFirst();
                result.addFirst(node.data);
                if(node.right!=null){
                    ll.addLast(node.right);
                }
                if(node.left!=null){
                    ll.addLast(node.left);
                }
            }
        }
        return result;
    }
}

class Solution {
    public Node buildTree(List<Integer> nodes) {
        // code here
        int n=nodes.size();
        if(n==0) return null;

        Node[] tree=new Node[n];

        for(int i=0;i<n;i++){
            tree[i]=new Node(nodes.get(i));
        }
        for(int i=0;i<n;i++){
            int left=2*i+1;
            int right=2*i+2;
            if(left<n){
                tree[i].left=tree[left];
            }
            if(right<n){
                tree[i].right=tree[right];
            }
        }

        return tree[0];
    }
}

class Solution {
    Map<Integer,Integer> map = new HashMap<>();
    int preOrderIndex=0;
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        for(int i=0;i<inorder.length;i++){
            map.put(inorder[i],i);
        }
        return build(preorder,0,inorder.length-1);
    }
    public TreeNode build(int[] preorder,int left,int right){
        if(left>right) return null;
        TreeNode root=new TreeNode(preorder[preOrderIndex++]);
        int inOrderIndex=map.get(root.val);
        root.left=build(preorder,left,inOrderIndex-1);
        root.right=build(preorder,inOrderIndex+1,right);
        return root;
    }
}

class Solution {
    public  boolean dfs(Node root){
        if(root==null){
            return true;
        }
        if(root.left==null && root.right==null){
            return true;
        }
       int left=(root.left!=null)? root.left.data : 0;
       int right=(root.right!=null)? root.right.data : 0;

       return (root.data== left+right) && dfs(root.left) && dfs(root.right);

    }
    public boolean isSumProperty(Node root) {

        return dfs(root);
    }
}
